import sys

import cv2
import numpy as np


def _extract_bottom_track(video_path, threshold, area_fraction):
    cap = cv2.VideoCapture(video_path)
    if not cap.isOpened():
        raise RuntimeError("Could not open video: " + video_path)

    ok, background = cap.read()
    if not ok:
        cap.release()
        raise RuntimeError("Could not read the first frame of: " + video_path)

    height, width = background.shape[:2]
    fps = cap.get(cv2.CAP_PROP_FPS)
    if not fps or fps != fps or fps <= 0:
        fps = 30.0

    min_area = area_fraction * width * height
    bottoms = [0]

    while True:
        ok, frame = cap.read()
        if not ok:
            break

        diff = cv2.absdiff(frame, background).max(axis=2)
        mask = (diff > threshold).astype(np.uint8) * 255
        mask = cv2.morphologyEx(
            mask, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8)
        )
        mask = cv2.morphologyEx(
            mask, cv2.MORPH_CLOSE, np.ones((9, 9), np.uint8)
        )

        count, labels, stats, centroids = cv2.connectedComponentsWithStats(
            mask, 8
        )
        bottom = 0
        for index in range(1, count):
            x, y, w, h, area = stats[index]
            if area >= min_area:
                candidate = y + h
                if candidate > bottom:
                    bottom = candidate
        bottoms.append(int(bottom))

    cap.release()
    return np.asarray(bottoms, dtype=np.float64), height, width, fps


def _find_jump(bottoms, height, fps):
    positive = bottoms[bottoms > 0]
    if positive.size == 0:
        return None

    ground_values = bottoms[bottoms > 0.55 * height]
    if ground_values.size == 0:
        ground_values = positive

    ground = float(np.percentile(ground_values, 90))
    contact_threshold = ground - 0.03 * height
    contact = bottoms >= contact_threshold

    runs = []
    start = None
    for index, value in enumerate(contact):
        if value and start is None:
            start = index
        elif not value and start is not None:
            runs.append((start, index - 1))
            start = None
    if start is not None:
        runs.append((start, len(contact) - 1))

    max_gap = max(6, int(round(fps)))

    gaps = []
    for (_, run_end), (next_start, _) in zip(runs, runs[1:]):
        gap_start = run_end + 1
        gap_end = next_start - 1
        gap_length = gap_end - gap_start + 1
        if gap_length < 2:
            continue
        lowest = float(bottoms[gap_start:next_start].min())
        excursion = ground - lowest
        gaps.append((excursion, gap_length, gap_start, next_start))

    if not gaps:
        return None

    strong = [
        gap
        for gap in gaps
        if gap[1] <= max_gap and gap[0] >= 0.06 * height
    ]
    if not strong:
        strong = [gap for gap in gaps if gap[1] <= max_gap]
    if not strong:
        strong = gaps

    strong.sort(key=lambda gap: (gap[0], gap[1]), reverse=True)
    _, _, takeoff, land = strong[0]
    return int(takeoff), int(land)


def analyze_video(video_path):
    thresholds = [30, 28, 32, 26, 34, 24, 36, 22, 38]
    area_fractions = [0.006, 0.004, 0.009]

    for area_fraction in area_fractions:
        for threshold in thresholds:
            bottoms, height, width, fps = _extract_bottom_track(
                video_path, threshold, area_fraction
            )
            result = _find_jump(bottoms, height, fps)
            if result is not None:
                return result

    raise RuntimeError("Could not detect a jump in: " + video_path)


def main():
    if len(sys.argv) > 1:
        video_path = sys.argv[1]
    else:
        video_path = "/app/example_video.mp4"

    takeoff, land = analyze_video(video_path)

    output_path = "/app/output.toml"
    with open(output_path, "w", encoding="utf-8") as output:
        output.write(
            "jump_takeoff_frame_number = {}\n".format(takeoff)
        )
        output.write(
            "jump_land_frame_number = {}\n".format(land)
        )


if __name__ == "__main__":
    main()
